@push('script')<script>(() => { const modal=document.getElementById('item-modal'), form=document.getElementById('item-form'), store=@json(route('quality.checklists.items.store')); modal.addEventListener('show.bs.modal', e=>{const b=e.relatedTarget, edit=b?.classList.contains('edit-item'); form.action=edit?b.dataset.action:store; document.getElementById('item-method').value=edit?'PUT':'POST'; form.quality_checklist_section_id.value=edit?b.dataset.section:form.quality_checklist_section_id.value; form.code.value=edit?b.dataset.code:''; form.question.value=edit?b.dataset.question:''; form.severity_sp.value=edit?b.dataset.sp:'Grave'; form.severity_qa.value=edit?b.dataset.qa:'Grave'; form.sort_order.value=edit?b.dataset.sort:0; form.active.checked=edit?b.dataset.active==='1':true; }); })();</script>@endpush
